import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.cNy3aYYk.js";const g=JSON.parse('{"title":"Multi-bank remittance + public invoice/quotation share links — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Multi-bank remittance + public invoice/quotation share links — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/billing-share-multi-bank-2026-10-10-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Multi-bank remittance + public invoice/quotation share links — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/billing-share-multi-bank-2026-10-10-production-readiness"}]]},"headers":[],"relativePath":"deployment/billing-share-multi-bank-2026-10-10-production-readiness.md","filePath":"deployment/billing-share-multi-bank-2026-10-10-production-readiness.md","lastUpdated":1791586880000}'),i={name:"deployment/billing-share-multi-bank-2026-10-10-production-readiness.md"};function d(s,e,r,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="multi-bank-remittance-public-invoice-quotation-share-links-—-production-readiness-audit" tabindex="-1">Multi-bank remittance + public invoice/quotation share links — Production Readiness Audit <a class="header-anchor" href="#multi-bank-remittance-public-invoice-quotation-share-links-—-production-readiness-audit" aria-label="Permalink to &quot;Multi-bank remittance + public invoice/quotation share links — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-10-10</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong></td></tr><tr><td><strong>Scope</strong></td><td>Settings → Branding <code>invoice_bank_accounts</code> (multi-account enable/disable); guest share links for invoices &amp; quotations (view + branded PDF); catalog <strong>invoices 1.11.0 → 1.12.0</strong>, <strong>quotations 1.9.0 → 1.10.0</strong></td></tr><tr><td><strong>Companion</strong></td><td><a href="/user-guide/invoices-overview">Invoices</a> · <a href="/user-guide/quotations-overview">Quotations</a> · <a href="/developer-guide/tenant-settings">Tenant settings</a> · <a href="/deployment/upgrade">Upgrade</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Workspaces can store up to ten remittance bank accounts and toggle which appear on invoice PDFs / guest share pages. Staff with send permission can mint opaque 90-day public share links; guests view the document and download the same branded Dompdf as CRM without logging in. Void (invoice) and reject/expire (quotation) clear tokens. Legacy flat <code>invoice_bank_*</code> keys still hydrate and sync from the <strong>first enabled</strong> account (cleared when none are enabled).</p><p><strong>Go / No-Go:</strong> <strong>Go</strong>.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze (guest pages under existing SPA hash routes; no parallel shell)</td><td><strong>Pass</strong></td></tr><tr><td>Token opacity (SHA-256 hash in DB; plaintext only in mint URL)</td><td><strong>Pass</strong></td></tr><tr><td>Expiry (90 days) + void/reject/expire clear link</td><td><strong>Pass</strong> — Pest</td></tr><tr><td>Entitlement-gated public routes (generic 404)</td><td><strong>Pass</strong></td></tr><tr><td>Rate limits (<code>document-share</code> / <code>document-share-pdf</code> by IP)</td><td><strong>Pass</strong></td></tr><tr><td>Multi-bank PDF + <code>payment_bank.bank_accounts</code> (enabled only)</td><td><strong>Pass</strong> — Pest + headed e2e</td></tr><tr><td>Legacy sync when all accounts disabled</td><td><strong>Pass</strong> — remediations A1</td></tr><tr><td>Catalog migrate-only + CatalogSeeder companion</td><td><strong>Pass</strong> — <strong>1.12.0</strong> / <strong>1.10.0</strong></td></tr><tr><td>Docs + CHANGELOG same delivery</td><td><strong>Pass</strong></td></tr><tr><td>Playwright headed one-session</td><td><strong>Pass</strong> — <code>npm run test:e2e:billing-share:headed</code> (4/4)</td></tr><tr><td>Pest (banks + share + catalog bump)</td><td><strong>Pass</strong></td></tr></tbody></table><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h2><h3 id="closed-audit-remediations" tabindex="-1">Closed (audit remediations) <a class="header-anchor" href="#closed-audit-remediations" aria-label="Permalink to &quot;Closed (audit remediations)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Resolution</th></tr></thead><tbody><tr><td>A1</td><td>Medium</td><td><code>toLegacyFlat()</code> fell back to a disabled account when none were enabled</td><td>Sync only from enabled accounts; all-disabled clears legacy keys + Pest</td></tr><tr><td>A2</td><td>Medium</td><td><code>document-share</code> throttle keyed by authenticated user id when present</td><td>Always key by IP (parity with PDF limiter)</td></tr><tr><td>A3</td><td>Medium</td><td>No deployment readiness page / developer-guide lag on public share + multi-bank</td><td>This page + invoices developer guide + upgrade + VitePress index</td></tr><tr><td>A4</td><td>Low</td><td>Bank remove control lacked accessible name for e2e</td><td><code>aria-label=&quot;Remove account N&quot;</code> + headed cleanup uses role</td></tr></tbody></table><h3 id="accepted-intentional-ops-—-not-defects" tabindex="-1">Accepted (intentional / ops — not defects) <a class="header-anchor" href="#accepted-intentional-ops-—-not-defects" aria-label="Permalink to &quot;Accepted (intentional / ops — not defects)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Notes</th></tr></thead><tbody><tr><td>R1</td><td>Info</td><td>Guest JSON includes <code>contact_name</code> / <code>company_name</code> for document context; SPA bank block shows enabled remittance only</td></tr><tr><td>R2</td><td>Info</td><td><strong>Copy share link</strong> is on dedicated record pages (not list peeks) — matches billing peek rules</td></tr><tr><td>R3</td><td>Ops</td><td>Deploy Backend + Frontend together; migrate-only — <strong>do not</strong> <code>db:seed</code></td></tr><tr><td>R4</td><td>Info</td><td>Quotation <strong>Copy accept link</strong> remains separate from public share</td></tr></tbody></table><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><h3 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h3><ul><li>Migration <code>2026_10_09_221135_add_public_view_tokens_to_billing_documents_table</code> (+ catalog bumps)</li><li><code>InvoiceBankAccounts</code> + settings validation / <code>TenantSettingService</code> sync</li><li><code>PublicInvoiceShareController</code> / <code>PublicQuotationShareController</code>; mint on invoice/quotation services</li><li>PDF Payment Information loops enabled <code>bank_accounts</code></li><li>Rate limiters <code>document-share</code> / <code>document-share-pdf</code></li><li>Pest: <code>InvoiceBankAccountsSettingTest</code>, <code>CustomerInvoicePublicShareTest</code>, <code>QuotationPublicShareTest</code>, <code>InvoicesQuotationsPublicShareBumpTest</code></li></ul><h3 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h3><ul><li>Settings → Branding multi-bank UI</li><li>Invoice/quotation <strong>Copy share link</strong>; guest <code>/#/view/invoices|quotations/:token</code> + PDF</li><li>Playwright: <code>e2e/tests/billing/billing.share-and-banks.headed.spec.ts</code> (<code>test:e2e:billing-share:headed</code>)</li></ul><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><ul><li>User / API / tenant-settings / changelog / upgrade / this readiness page</li></ul><h2 id="test-evidence" tabindex="-1">Test evidence <a class="header-anchor" href="#test-evidence" aria-label="Permalink to &quot;Test evidence&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>herd php artisan test --compact tests/Feature/Tenant/Settings/InvoiceBankAccountsSettingTest.php tests/Feature/Tenant/CustomerInvoice/CustomerInvoicePublicShareTest.php tests/Feature/Tenant/Quotation/QuotationPublicShareTest.php tests/Feature/Central/Catalog/InvoicesQuotationsPublicShareBumpTest.php</span></span></code></pre></div><p>Pest: <strong>12 passed</strong> (81 assertions).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>E2E_BROWSER_CHANNEL=chrome E2E_VIDEO=off npm run test:e2e:billing-share:headed</span></span></code></pre></div><p>Playwright headed (<code>--workers=1</code>, one workspace login): <strong>4 passed</strong> — banks (one disabled), invoice validation + share, guest invoice PDF, quotation share + guest PDF.</p><h2 id="operator-checklist" tabindex="-1">Operator checklist <a class="header-anchor" href="#operator-checklist" aria-label="Permalink to &quot;Operator checklist&quot;">​</a></h2><ol><li>Deploy Backend → <code>php artisan migrate --force</code> (<strong>do not</strong> <code>db:seed</code>)</li><li>Confirm catalog: <code>invoices</code> <strong>1.12.0</strong>, <code>quotations</code> <strong>1.10.0</strong></li><li>Deploy Frontend SPA</li><li>Smoke: Settings → Branding two banks / one disabled → send invoice → Copy share link → guest view + PDF (only enabled bank) → void → link 404; same for sent quotation share (accept link still works)</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/deployment/upgrade">Upgrade</a></li><li><a href="/changelog/">Changelog</a></li><li><a href="/developer-guide/invoices">Invoices developer guide</a></li><li><a href="/developer-guide/tenant-settings">Tenant settings</a></li></ul>',28)])])}const p=t(i,[["render",d]]);export{g as __pageData,p as default};
